/*
 * Interactive 3D view of cluster resources, based on three.js and the 3D
 * representations of infrastructures generated by RacksDB in glTF format. This
 * module is independent of Vue, it is loaded dynamically to keep three.js out of
 * the main bundle.
 */

import {
  AmbientLight,
  DirectionalLight,
  HemisphereLight,
  PerspectiveCamera,
  Raycaster,
  Scene,
  Vector2,
  Vector3,
  WebGLRenderer
} from 'three'
import type { Mesh, Object3D } from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import type { GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js'
import type { SlurmNode } from '@/composables/gateway/slurm/types'
import type { ResourcesRepresentation } from '@/stores/runtime/resources'
import {
  computeFocus,
  disposeObject,
  findEquipment,
  indexEquipment,
  isVisible,
  parseGlb,
  setTexturesAnisotropy
} from '@/lib/resources3d/scene'
import type { Focus } from '@/lib/resources3d/scene'
import {
  CAMERA_FOV,
  KeyboardNavigator,
  TRANSITION_DURATION,
  Turntable,
  cameraAzimuth,
  cameraDepthRange,
  createTransition,
  defaultTurntableDistance,
  initialPosition,
  setupControls,
  stepTransition,
  zoomTurntableDistance
} from '@/lib/resources3d/camera'
import type { CameraMode, CameraTransition } from '@/lib/resources3d/camera'
import { ScenePainter } from '@/lib/resources3d/paint'

export type { CameraMode } from '@/lib/resources3d/camera'

/* Maximal distance in pixels between pointer down and up events to consider them
 * as a click, rather than a drag to move the camera. */
const CLICK_SLOP_PX = 4

export interface ResourcesViewerCallbacks {
  /* Called when the hovered node changes, with the node name (or null when no
   * node is hovered) and the pointer position relative to the container. */
  onHover: (name: string | null, x: number, y: number) => void
  /* Called when a node is clicked. */
  onSelect: (name: string) => void
  /* Called when the camera mode changes. */
  onCameraModeChange: (mode: CameraMode) => void
}

function prefersReducedMotion(): boolean {
  return (
    typeof window.matchMedia === 'function' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  )
}

export class ResourcesViewer {
  private renderer: WebGLRenderer
  private scene = new Scene()
  private camera = new PerspectiveCamera(CAMERA_FOV, 1, 0.05, 1000)
  private controls: OrbitControls
  private focus: Focus
  private painter: ScenePainter
  private raycaster = new Raycaster()
  private keyboard = new KeyboardNavigator()
  private turntable = new Turntable()
  private resizeObserver: ResizeObserver | null = null
  private animationFrame = 0
  private lastFrame = 0
  private mode: CameraMode = 'free'
  // Current eased camera transition, controls are disabled while it is running.
  private transition: CameraTransition | null = null
  // Point looked by camera when controls are disabled
  private lookTarget = new Vector3()
  // Last pointer position in normalized device coordinates, to pick hovered node
  // on next frame.
  private pointer: Vector2 | null = null
  private pointerOffset = { x: 0, y: 0 }
  private pointerDown: { x: number; y: number } | null = null
  private hovered: string | null = null
  // Names of equipment objects of the scene
  private names = new Map<Object3D, string>()
  // Names of Slurm nodes that can be hovered and selected
  private selectable = new Set<string>()

  constructor(
    private container: HTMLElement,
    private gltf: GLTF,
    private callbacks: ResourcesViewerCallbacks
  ) {
    // Transparent background, the page background is visible behind the scene in
    // both light and dark modes.
    this.renderer = new WebGLRenderer({ antialias: true, alpha: true })
    this.renderer.setPixelRatio(window.devicePixelRatio)
    this.renderer.setClearColor(0x000000, 0)
    const canvas = this.renderer.domElement
    canvas.classList.add('block', 'h-full', 'w-full', 'outline-none')
    // Make the canvas focusable to receive keyboard events.
    canvas.tabIndex = 0
    canvas.setAttribute('aria-label', 'Cluster resources 3D view')
    container.appendChild(canvas)

    this.scene.add(new AmbientLight(0xffffff, 0.8))
    this.scene.add(new HemisphereLight(0xf5f7ff, 0x8a9099, 0.5))
    const key = new DirectionalLight(0xffffff, 0.8)
    key.position.set(5, 14, 8)
    this.scene.add(key)
    const fill = new DirectionalLight(0xffffff, 0.35)
    fill.position.set(-6, 9, -4)
    this.scene.add(fill)
    this.scene.add(gltf.scene)

    setTexturesAnisotropy(gltf.scene, this.renderer.capabilities.getMaxAnisotropy())
    const equipment = indexEquipment(gltf, gltf.scene)
    for (const [name, object] of equipment) this.names.set(object, name)
    this.painter = new ScenePainter(equipment)

    this.focus = computeFocus(gltf.scene)
    const { near, far } = cameraDepthRange(this.focus)
    this.camera.near = near
    this.camera.far = far
    this.camera.updateProjectionMatrix()

    // These listeners are registered before the controls, so they are called
    // first.
    canvas.addEventListener('pointerdown', this.onPointerDown)
    canvas.addEventListener('pointermove', this.onPointerMove)
    canvas.addEventListener('pointerup', this.onPointerUp)
    canvas.addEventListener('pointerleave', this.onPointerLeave)
    canvas.addEventListener('wheel', this.onWheel, { passive: false })
    canvas.addEventListener('keydown', this.onKeyDown)
    canvas.addEventListener('keyup', this.onKeyUp)
    canvas.addEventListener('blur', this.onBlur)
    window.addEventListener('blur', this.onBlur)

    this.controls = new OrbitControls(this.camera, canvas)
    this.controls.enableDamping = true
    setupControls(this.controls, this.focus)
    this.camera.position.copy(initialPosition(this.focus, this.camera.fov))
    this.controls.target.copy(this.focus.center)
    this.controls.update()

    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObserver = new ResizeObserver(() => this.resize())
      this.resizeObserver.observe(container)
    }
    this.resize()
    this.animate()
    // Give keyboard focus to the scene, so arrows move the camera right away.
    this.focusKeyboard()
  }

  /* Give keyboard focus to the scene canvas. */
  focusKeyboard() {
    this.renderer.domElement.focus({ preventScroll: true })
  }

  /* Paint nodes with the given Slurm nodes and representation. */
  setNodes(nodes: SlurmNode[], mode: ResourcesRepresentation) {
    this.painter.paint(nodes, mode)
    this.selectable = new Set(nodes.map((node) => node.name))
    // Hovered node may not be selected anymore.
    if (this.hovered && !this.selectable.has(this.hovered)) {
      this.setHovered(null)
    }
  }

  /* Switch camera mode. In turntable mode, the camera moves with an eased
   * transition to the orbit around the racks and rotates. In free mode, the camera
   * stops where it is and it is controlled by the user. */
  setCameraMode(mode: CameraMode) {
    if (mode === 'turntable') {
      if (this.mode === 'turntable') return
      this.setModeValue('turntable')
      this.keyboard.clear()
      this.turntable.start(
        cameraAzimuth(this.camera.position, this.focus),
        defaultTurntableDistance(this.focus, this.camera.fov)
      )
      this.startTransition(this.turntable.position(this.focus), this.focus.center)
      return
    }
    if (this.mode === 'free' && !this.transition) return
    this.transition = null
    this.setModeValue('free')
    this.enableControls(this.lookTarget)
  }

  /* Move camera with an eased transition to its initial position, in free mode. */
  resetCamera() {
    this.setModeValue('free')
    this.startTransition(initialPosition(this.focus, this.camera.fov), this.focus.center)
  }

  resize() {
    const { clientWidth: width, clientHeight: height } = this.container
    if (!width || !height) return
    this.camera.aspect = width / height
    this.camera.updateProjectionMatrix()
    this.renderer.setSize(width, height, false)
  }

  dispose() {
    cancelAnimationFrame(this.animationFrame)
    this.resizeObserver?.disconnect()
    const canvas = this.renderer.domElement
    canvas.removeEventListener('pointerdown', this.onPointerDown)
    canvas.removeEventListener('pointermove', this.onPointerMove)
    canvas.removeEventListener('pointerup', this.onPointerUp)
    canvas.removeEventListener('pointerleave', this.onPointerLeave)
    canvas.removeEventListener('wheel', this.onWheel)
    canvas.removeEventListener('keydown', this.onKeyDown)
    canvas.removeEventListener('keyup', this.onKeyUp)
    canvas.removeEventListener('blur', this.onBlur)
    window.removeEventListener('blur', this.onBlur)
    this.controls.dispose()
    this.painter.dispose()
    disposeObject(this.scene)
    this.renderer.dispose()
    this.renderer.forceContextLoss()
    canvas.remove()
  }

  private setModeValue(mode: CameraMode) {
    if (mode === this.mode) return
    this.mode = mode
    this.callbacks.onCameraModeChange(mode)
  }

  /* Start eased transition of camera from its current position and target to the
   * given position and target, with controls disabled. */
  private startTransition(position: Vector3, target: Vector3) {
    // When a transition is already running, the controls are already disabled and
    // the camera looks at lookTarget.
    const fromTarget = this.controls.enabled ? this.controls.target : this.lookTarget
    this.transition = createTransition(
      this.camera.position,
      position,
      fromTarget,
      target,
      prefersReducedMotion() ? 0 : TRANSITION_DURATION
    )
    this.lookTarget.copy(fromTarget)
    this.controls.enabled = false
  }

  /* Give camera control back to the user, looking at the given target. */
  private enableControls(target: Vector3) {
    if (this.controls.enabled) return
    // Discard controls inertia remaining from user moves before controls were
    // disabled: an update without damping consumes it, then camera is restored.
    const position = this.camera.position.clone()
    this.controls.enableDamping = false
    this.controls.update()
    this.controls.enableDamping = true
    this.camera.position.copy(position)
    this.controls.target.copy(target)
    this.controls.enabled = true
    this.controls.update()
  }

  private animate = () => {
    this.animationFrame = requestAnimationFrame(this.animate)
    const now = performance.now()
    // Limit delta to avoid jumps when the page was in background.
    const delta = this.lastFrame ? Math.min((now - this.lastFrame) / 1000, 0.1) : 0
    this.lastFrame = now
    if (this.pointer) {
      this.pick(this.pointer)
      this.pointer = null
    }
    if (this.transition) {
      const finished = stepTransition(this.transition, delta, this.camera.position, this.lookTarget)
      this.camera.lookAt(this.lookTarget)
      if (finished) {
        this.transition = null
        if (this.mode === 'free') this.enableControls(this.lookTarget)
      }
    } else if (this.mode === 'turntable') {
      this.camera.position.copy(this.turntable.step(this.focus, delta))
      this.lookTarget.copy(this.focus.center)
      this.camera.lookAt(this.lookTarget)
    } else {
      this.keyboard.step(delta, this.camera, this.controls, this.container.clientHeight)
      this.controls.update(delta)
    }
    this.renderer.render(this.scene, this.camera)
  }

  private onPointerDown = (event: PointerEvent) => {
    this.pointerDown = { x: event.clientX, y: event.clientY }
    this.renderer.domElement.focus({ preventScroll: true })
  }

  private onPointerMove = (event: PointerEvent) => {
    const rect = this.renderer.domElement.getBoundingClientRect()
    if (!rect.width || !rect.height) return
    this.pointerOffset = { x: event.clientX - rect.left, y: event.clientY - rect.top }
    this.pointer = new Vector2(
      (this.pointerOffset.x / rect.width) * 2 - 1,
      -(this.pointerOffset.y / rect.height) * 2 + 1
    )
  }

  private onPointerUp = (event: PointerEvent) => {
    const down = this.pointerDown
    this.pointerDown = null
    if (!down) return
    const dx = event.clientX - down.x
    const dy = event.clientY - down.y
    if (dx * dx + dy * dy > CLICK_SLOP_PX * CLICK_SLOP_PX) return
    this.onPointerMove(event)
    if (this.pointer) {
      this.pick(this.pointer)
      this.pointer = null
    }
    if (this.hovered) this.callbacks.onSelect(this.hovered)
  }

  private onPointerLeave = () => {
    this.pointer = null
    this.pointerDown = null
    this.setHovered(null)
  }

  private onWheel = (event: WheelEvent) => {
    // In free mode, the wheel is handled by the controls to zoom.
    if (this.mode !== 'turntable') return
    event.preventDefault()
    this.turntable.distance = zoomTurntableDistance(
      this.turntable.distance,
      Math.sign(event.deltaY),
      this.focus
    )
  }

  private onKeyDown = (event: KeyboardEvent) => {
    if (this.mode !== 'free' || this.transition) return
    if (this.keyboard.keydown(event)) event.preventDefault()
  }

  private onKeyUp = (event: KeyboardEvent) => {
    this.keyboard.keyup(event)
  }

  private onBlur = () => {
    this.keyboard.clear()
  }

  /* Pick the node under the pointer, given in normalized device coordinates. */
  private pick(pointer: Vector2) {
    this.raycaster.setFromCamera(pointer, this.camera)
    // Only consider visible meshes: equipment edges are lines with large picking
    // threshold, and three.js raycaster does not skip hidden objects (ex: cores
    // bars in nodes mode).
    const hit = this.raycaster
      .intersectObject(this.gltf.scene, true)
      .find(
        (intersection) => (intersection.object as Mesh).isMesh && isVisible(intersection.object)
      )
    const equipment = hit ? findEquipment(hit.object) : null
    this.setHovered(equipment ? this.nodeName(equipment) : null)
  }

  /* Return the name of the given equipment if it is a painted node selected in
   * Slurm nodes, or null. */
  private nodeName(equipment: Object3D): string | null {
    const name = this.names.get(equipment)
    if (name && this.painter.has(name) && this.selectable.has(name)) return name
    return null
  }

  private setHovered(name: string | null) {
    if (name !== this.hovered) {
      this.hovered = name
      this.painter.highlight(name)
      this.renderer.domElement.style.cursor = name ? 'pointer' : ''
    }
    this.callbacks.onHover(name, this.pointerOffset.x, this.pointerOffset.y)
  }
}

export async function createResourcesViewer(
  container: HTMLElement,
  data: ArrayBuffer,
  callbacks: ResourcesViewerCallbacks
): Promise<ResourcesViewer> {
  return new ResourcesViewer(container, await parseGlb(data), callbacks)
}
